(6343453, 939371, 88718, '<td valign="top">Nicely posed and well executed. Top 10</td>', 'Nicely posed and well executed. Top 10', '2011-03-07 05:31:36.000000', NULL, 1),
(6343454, 939331, 88718, '<td valign="top">What a wonderful texture. The lighting could have been more vivid though</td>', 'What a wonderful texture. The lighting could have been more vivid though', '2011-03-07 05:32:14.000000', NULL, 1),
(6343455, 939149, 88718, '<td valign="top">Good effort. The lighting was very harsh here thus the shadows in the "holes" made by the strawberries is very dark. You should try this again using milk. It works better, looks like cream and you can wash the strawberries for multiple takes without making too much mess.</td>', 'Good effort. The lighting was very harsh here thus the shadows in the "holes" made by the strawberries is very dark. You should try this again using milk. It works better, looks like cream and you can wash the strawberries for multiple takes without making too much mess.', '2011-03-07 05:34:18.000000', NULL, 1),
(6343456, 939527, 88718, '<td valign="top">Nice abstract.</td>', 'Nice abstract.', '2011-03-07 05:34:56.000000', NULL, 1),
