INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6343870, 939477, 54446, '<td valign="top">This is one of my top picks in this challenge.  Love the steam (smoke) and the colors.  I''m not too enamored by the total black bg on the left side.  Sort of makes the red pepper too "cut out" looking.  Otherwise, very nice.</td>', 'This is one of my top picks in this challenge.  Love the steam (smoke) and the colors.  I''m not too enamored by the total black bg on the left side.  Sort of makes the red pepper too "cut out" looking.  Otherwise, very nice.', '2011-03-07 10:01:01.000000', NULL, 1),
(6343882, 939408, 96751, '<td valign="top">Beautiful bokeh!</td>', 'Beautiful bokeh!', '2011-03-07 10:02:18.000000', NULL, 1),
(6343894, 939320, 54446, '<td valign="top">Super composition.  Two colors... well done.   I like the bubbles a lot, but find the blurred area not as natural.  Just a little overprocessed for me.  Gave this a 9.</td>', 'Super composition.  Two colors... well done.   I like the bubbles a lot, but find the blurred area not as natural.  Just a little overprocessed for me.  Gave this a 9.', '2011-03-07 10:05:42.000000', NULL, 1),
(6343895, 939280, 54446, '<td valign="top">Beautiful shot.  Great face detail.  Sharp where it counts.  I''m certain you''ll encounter resistance to the closeness of brown and gold, but I like it anyway.  9</td>', 'Beautiful shot.  Great face detail.  Sharp where it counts.  I''m certain you''ll encounter resistance to the closeness of brown and gold, but I like it anyway.  9', '2011-03-07 10:06:56.000000', NULL, 1),
(6343900, 939445, 54446, '<td valign="top">Subtle and well done.  In general, just slightly underexposed on my monitor, but it is a very nice SL.</td>', 'Subtle and well done.  In general, just slightly underexposed on my monitor, but it is a very nice SL.', '2011-03-07 10:07:45.000000', NULL, 1),
(6343926, 938993, 122892, '<td valign="top">Awesome!</td>', 'Awesome!', '2011-03-07 10:30:44.000000', NULL, 1),
(6343929, 939273, 122892, '<td valign="top">LOL! Interesting.</td>', 'LOL! Interesting.', '2011-03-07 10:31:31.000000', NULL, 1),
(6343930, 939527, 26464, '<td valign="top">lovely study of colour and texture</td>', 'lovely study of colour and texture', '2011-03-07 10:32:10.000000', NULL, 1),
(6343935, 939318, 26464, '<td valign="top">haha. 7</td>', 'haha. 7', '2011-03-07 10:33:42.000000', NULL, 1),
(6343937, 939371, 26464, '<td valign="top">probably a ribbon... although there''s only one obvious colour. but really nice.</td>', 'probably a ribbon... although there''s only one obvious colour. but really nice.', '2011-03-07 10:34:59.000000', NULL, 1),
(6343941, 938868, 26464, '<td valign="top">wow I took the exact same shot and didn''t enter it... glad I didn''t yours is better...</td>', 'wow I took the exact same shot and didn''t enter it... glad I didn''t yours is better...', '2011-03-07 10:37:52.000000', NULL, 1),
(6343943, 939484, 26464, '<td valign="top">a sad commentary but good photo</td>', 'a sad commentary but good photo', '2011-03-07 10:38:18.000000', NULL, 1),
(6343983, 939280, 114225, '<td valign="top">Beautiful details and clarity.</td>', 'Beautiful details and clarity.', '2011-03-07 11:06:46.000000', NULL, 1),
(6343985, 938948, 114225, '<td valign="top">You must be a wizard of some kind! :)<br/>Neat use of a minimalistic style. This could use slightly better lighting, maybe by adding a light source from the lower left.</td>', 'You must be a wizard of some kind! :)Neat use of a minimalistic style. This could use slightly better lighting, maybe by adding a light source from the lower left.', '2011-03-07 11:08:33.000000', NULL, 1),
(6343989, 939429, 114225, '<td valign="top">Nice idea to play with repeating elements. The floor being peach adds a third color, which I won''t take off for in this case. But I am taking points off for quality reasons.<br/> <br/>All of those reflections in the bottles are very distracting. Try using a softer/diffused light source. Also we can see some of the expiration date printing, which is also distracting. Hopefully you can use this information to improve your photography!</td>', 'Nice idea to play with repeating elements. The floor being peach adds a third color, which I won''t take off for in this case. But I am taking points off for quality reasons. All of those reflections in the bottles are very distracting. Try using a softer/diffused light source. Also we can see some of the expiration date printing, which is also distracting. Hopefully you can use this information to improve your photography!', '2011-03-07 11:11:04.000000', NULL, 1),
(6343990, 938912, 114225, '<td valign="top">I like the catch lights in the candies. Just soft enough to not be a distraction.</td>', 'I like the catch lights in the candies. Just soft enough to not be a distraction.', '2011-03-07 11:11:44.000000', NULL, 1),
(6343992, 939012, 114225, '<td valign="top">Cool find. Did the glass really create these colors, or did you do it in post processing?</td>', 'Cool find. Did the glass really create these colors, or did you do it in post processing?', '2011-03-07 11:12:08.000000', NULL, 1),
(6343994, 939292, 114225, '<td valign="top">You know, I thought of doing a car light for this. But in the end, I couldn''t make it interesting. The play between yellow and red is very nice.</td>', 'You know, I thought of doing a car light for this. But in the end, I couldn''t make it interesting. The play between yellow and red is very nice.', '2011-03-07 11:13:40.000000', NULL, 1),
(6343997, 939510, 114225, '<td valign="top">I like the lighting. The shadows add a bit of depth.</td>', 'I like the lighting. The shadows add a bit of depth.', '2011-03-07 11:27:43.000000', NULL, 1),
(6344006, 939352, 114225, '<td valign="top">I like how you accomplished the selective de-saturation here. Gives a cool separation of the lynx from the background.</td>', 'I like how you accomplished the selective de-saturation here. Gives a cool separation of the lynx from the background.', '2011-03-07 11:30:56.000000', NULL, 1),
(6344008, 939231, 114225, '<td valign="top">Cute! The blue blanket is what makes this photo really work for me.</td>', 'Cute! The blue blanket is what makes this photo really work for me.', '2011-03-07 11:31:30.000000', NULL, 1),
